-- Post-event badge snapshots, collected from /sync on badge.hackthenorth.com.
--
-- Each synced badge produces one immutable row holding the firmware's v1
-- `fs_mirror` document, unchanged. Clients may insert only `dump`: the UUID
-- and the server timestamp are generated by Postgres, so repeated submissions
-- create new rows and nothing overwrites an earlier snapshot.
--
-- Access: RLS is on. Browsers use the publishable key and may INSERT only;
-- there are no SELECT/UPDATE/DELETE grants or policies for anon or
-- authenticated users. Organizers read rows through the Supabase dashboard or
-- a server-side key. The snapshot can include contact details and the Solana
-- wallet backup, so keep public reads disabled and choose retention
-- deliberately. Anonymous submissions are unverified data, not authenticated
-- proof of badge ownership or scores.
--
-- Applied with the same `supabase db push` as the other migrations in this
-- directory (see ../../README.md). The browser contract is documented in
-- ../../../website/supabase/README.md.

create table if not exists public.badge_dumps (
  dump_id uuid primary key default gen_random_uuid(),
  dumped_at timestamptz not null default clock_timestamp(),
  dump jsonb not null,
  constraint badge_dump_format check (
    jsonb_typeof(dump) = 'object'
    and dump @> '{"v": 1, "kind": "fs_mirror"}'::jsonb
    and dump ? 'files'
    and jsonb_typeof(dump -> 'files') = 'object'
    and octet_length(dump::text) <= 131072
  )
);

create index if not exists badge_dumps_dumped_at_idx
  on public.badge_dumps (dumped_at desc);

alter table public.badge_dumps enable row level security;

revoke all on public.badge_dumps from anon, authenticated;

-- Append-only browser uploads: insert the `dump` column only. Send
-- `Prefer: return=minimal`; the insert needs no public SELECT access.
grant insert (dump) on public.badge_dumps to anon;

drop policy if exists "Accept anonymous badge snapshots" on public.badge_dumps;
create policy "Accept anonymous badge snapshots"
  on public.badge_dumps for insert to anon with check (true);

comment on table public.badge_dumps is
  'Append-only post-event badge snapshots. May contain contact and wallet data. Never expose public reads.';
